teams: Dict[str, TeamData] = {}
teams_lock = threading.Lock()

snapshots: Dict[str, dict] = {}
snapshots_lock = threading.Lock()

rate_limits: Dict[str, list] = defaultdict(list)
rate_limit_lock = threading.Lock()
RATE_LIMIT = 100

# SQL injection patterns
SQL_INJECTION_PATTERNS = [
    re.compile(r"'\s*(OR|AND)\s", re.IGNORECASE),
    re.compile(r"'\s*;"),
    re.compile(r"\bDROP\b\s+\bTABLE\b", re.IGNORECASE),
    re.compile(r"\bSELECT\b.*\bFROM\b", re.IGNORECASE),
    re.compile(r"\bUNION\b\s+\bSELECT\b", re.IGNORECASE),
    re.compile(r"\bSELECT\b\s+\*"),
]


def _check_sql_injection(text: str) -> bool:
    for pattern in SQL_INJECTION_PATTERNS:
        if pattern.search(text):
            return True
    return False


def _check_rate_limit(team_id: str) -> bool:
    """Returns True if rate limit is exceeded"""
    now = time.time()
    with rate_limit_lock:
        rate_limits[team_id] = [t for t in rate_limits[team_id] if now - t < 60]
        if len(rate_limits[team_id]) >= RATE_LIMIT:
            return True
        rate_limits[team_id].append(now)
        return False


def _validate_team(team_id: str) -> Optional[TeamData]:
    """Validate and return team, or None"""
    with teams_lock:
        return teams.get(team_id)


def _validate_todo_data(data: dict) -> Optional[str]:
    """Validate todo creation data, return error message or None"""
    if not data or not isinstance(data, dict):
        return "Invalid request data"

    # Title validation
    if 'title' not in data:
        return "Missing title"
    title = data['title']
    if not isinstance(title, str) or not title.strip():
        return "Invalid title"
    if len(title) > 1000:
        return "Title too long"

    # SQL injection check
    if _check_sql_injection(title):
        return "SQL injection detected"

    # Tags validation
    if 'tags' in data:
        if not isinstance(data['tags'], list):
            return "Tags must be an array"
        for tag in data['tags']:
            if not isinstance(tag, str):
                return "Tags must be strings"
            if len(tag) > 100:
                return "Tag too long"

    # Metadata validation
    if 'metadata' in data:
        if not isinstance(data['metadata'], dict):
            return "Metadata must be an object"

    return None


def _format_todo(todo: dict) -> dict:
    return {
        "id": todo["id"],
        "title": todo["title"],
        "team_id": todo["team_id"],
        "completed": todo["completed"],
        "version": todo["version"],
        "created_at": todo["created_at"],
        "updated_at": todo["updated_at"],
        "tags": todo["tags"],
        "metadata": todo["metadata"]
    }


