# ============== API ENDPOINTS ==============

@app.route('/teams', methods=['POST'])
def create_team():
    # Parse JSON
    data = request.get_json(force=True, silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    # Validate name
    name = data.get('name')
    if not name or not isinstance(name, str) or not name.strip():
        return jsonify({"error": "Bad request", "message": "Missing or invalid name"}), 400

    # Validate capacity
    capacity = data.get('capacity')
    if capacity is None:
        return jsonify({"error": "Bad request", "message": "Missing capacity"}), 400
    if not isinstance(capacity, int) or isinstance(capacity, bool):
        return jsonify({"error": "Bad request", "message": "Invalid capacity"}), 400
    if capacity <= 0:
        return jsonify({"error": "Bad request", "message": "Invalid capacity"}), 400

    # Create team
    team_id = str(uuid.uuid4())
    team = TeamData(name.strip(), capacity, team_id)

    with teams_lock:
        teams[team_id] = team

    return jsonify({
        "team_id": team_id,
        "name": team.name,
        "capacity": team.capacity,
        "created_at": team.created_at
    }), 201


@app.route('/teams/<team_id>/stats', methods=['GET'])
def get_team_stats(team_id):
    # Check if header team_id matches URL team_id
    if g.team_id != team_id:
        return jsonify({"error": "Forbidden"}), 403

    team = g.team
    with team.lock:
        total = len(team.todos)
        completed = sum(1 for t in team.todos.values() if t["completed"])
        capacity_pct = (total / team.capacity * 100) if team.capacity > 0 else 0.0

    return jsonify({
        "total_todos": total,
        "completed": completed,
        "capacity_used": f"{capacity_pct:.1f}%"
    })


@app.route('/todos', methods=['GET'])
def get_todos():
    team = g.team

    # Parse query parameters
    page_str = request.args.get('page', '1')
    try:
        page = int(page_str)
    except (ValueError, TypeError):
        return jsonify({"error": "Bad request", "message": "Invalid page number"}), 400

    if page < 1:
        return jsonify({"error": "Bad request", "message": "Invalid page number"}), 400

    # Parse filters
    completed_filter = request.args.get('completed')
    if completed_filter is not None:
        if completed_filter.lower() == 'true':
            completed_filter = True
        elif completed_filter.lower() == 'false':
            completed_filter = False
        else:
            return jsonify({"error": "Bad request", "message": "Invalid completed filter"}), 400

    tag_filter = request.args.get('tag')

    # Parse sort
    sort_by = request.args.get('sort', 'created_asc')
    valid_sorts = ['created_asc', 'created_desc', 'title']
    if sort_by not in valid_sorts:
        return jsonify({"error": "Bad request", "message": "Invalid sort parameter"}), 400

    with team.lock:
        todos = list(team.todos.values())

    # Apply filters
    if completed_filter is not None:
        todos = [t for t in todos if t["completed"] == completed_filter]
    if tag_filter:
        todos = [t for t in todos if tag_filter in t.get("tags", [])]

    # Apply sorting
    if sort_by == 'created_asc':
        todos.sort(key=lambda t: t["created_at"])
    elif sort_by == 'created_desc':
        todos.sort(key=lambda t: t["created_at"], reverse=True)
    elif sort_by == 'title':
        todos.sort(key=lambda t: t["title"])

    total = len(todos)
    page_size_max = 50
    start = (page - 1) * page_size_max
    end = start + page_size_max
    page_todos = todos[start:end]

    next_cursor = page + 1 if end < total else None

    return jsonify({
        "todos": [_format_todo(t) for t in page_todos],
        "page": page,
        "page_size": len(page_todos),
        "next_cursor": next_cursor,
        "total": total
    })


