    if not isinstance(data, dict):
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    with team.lock:
        todo = team.todos.get(todo_id)

        if not todo or todo["team_id"] != team.id:
            return jsonify({"error": "Todo not found"}), 404

        if todo["version"] != provided_version:
            return jsonify({
                "error": "Version mismatch",
                "current_version": todo["version"],
                "provided_version": provided_version
            }), 409

        # Validate title if provided
        if 'title' in data:
            title = data['title']
            if not isinstance(title, str) or not title.strip():
                return jsonify({"error": "Bad request", "message": "Invalid title"}), 400
            if len(title) > 1000:
