@app.route('/todos/batch', methods=['POST'])
def batch_update_todos():
    team = g.team

    # Parse JSON
    data = request.get_json(force=True, silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    # Check for updates field
    if 'updates' not in data:
        return jsonify({"error": "Bad request", "message": "Missing updates field"}), 400

    updates = data['updates']
    if not isinstance(updates, list):
        return jsonify({"error": "Bad request", "message": "Updates must be an array"}), 400

    # Size limit
    if len(updates) > 100:
        return jsonify({"error": "Bad request", "message": "Too many updates"}), 400

    # Validate each update item
    for item in updates:
        if not isinstance(item, dict):
            return jsonify({"error": "Bad request", "message": "Invalid update item"}), 400
        if 'id' not in item:
            return jsonify({"error": "Bad request", "message": "Missing id in update"}), 400

    # Empty batch
    if len(updates) == 0:
        return jsonify({"updated": [], "count": 0})

    with team.lock:
        # Check all todos exist and belong to team
        todo_refs = []
        for item in updates:
            todo = team.todos.get(item['id'])
            if not todo or todo["team_id"] != team.id:
                return jsonify({"error": "Todo not found"}), 404
            todo_refs.append((item, todo))

        # Validate all updates
        for item, todo in todo_refs:
            if 'title' in item:
                title = item['title']
                if not isinstance(title, str) or not title.strip():
                    return jsonify({"error": "Bad request", "message": "Invalid title"}), 400
                if len(title) > 1000:
                    return jsonify({"error": "Bad request", "message": "Title too long"}), 400

        # Apply all updates
        updated = []
        now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        for item, todo in todo_refs:
            updatable = ['title', 'completed', 'tags', 'metadata']
            for field in updatable:
                if field in item:
                    todo[field] = item[field]
            todo["version"] += 1
            todo["updated_at"] = now
            updated.append(copy.deepcopy(todo))

    return jsonify({"updated": [_format_todo(t) for t in updated], "count": len(updated)})


@app.route('/todos/export', methods=['GET'])
def export_todos():
    team = g.team

    snapshot_id = str(uuid.uuid4())

    with team.lock:
        todos_copy = copy.deepcopy(list(team.todos.values()))
        todo_count = len(todos_copy)

    with snapshots_lock:
        snapshots[snapshot_id] = {
            "team_id": team.id,
            "todos": todos_copy,
            "created_at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        }

    return jsonify({
        "snapshot_id": snapshot_id,
        "message": "Snapshot created for team",
